import{_ as l,c as i,o,a4 as t,ad as r}from"./chunks/framework.CnbusAkP.js";const f=JSON.parse('{"title":"导航流程","description":"","frontmatter":{},"headers":[],"relativePath":"browser/浏览器工作原理/3_导航流程.md","filePath":"browser/浏览器工作原理/3_导航流程.md"}'),e={name:"browser/浏览器工作原理/3_导航流程.md"},s=t('<h1 id="导航流程" tabindex="-1">导航流程 <a class="header-anchor" href="#导航流程" aria-label="Permalink to &quot;导航流程&quot;">​</a></h1><p>经典问题：在浏览器里，从输入URL到页面展示，这中间发生了什么</p><p>整个过程需要浏览器各个进程之间配合，如下图</p><p><img src="'+r+'" alt="示意图"></p><ol><li><p><strong>用户输入</strong></p><ul><li>地址栏输入内容后，浏览器判断是搜索还是请求URL，如果是URL就把内容加上协议</li><li>输入回车之后浏览器有一个beforeunload事件，允许在页面退出前执行一些操作，比如询问是否离开当前页，beforeunload事件后标签页进入加载中状态，目前还是之前打开的页面，等提交文档阶段才会替换</li></ul></li><li><p><strong>URL请求过程</strong></p><ul><li>浏览器进程通过IPC把URL请求发送至网络进程，网络进程发起真正的URL请求流程</li><li>首先查询本地是否有缓存，如果没有就直接进入网络请求流程，进行DNS解析获取IP，利用IP与服务器建立TCP连接</li><li>建立TCP连接后浏览器构建请求行、请求头信息，发送给服务器</li><li>服务器收到请求信息后，生成响应行、响应头、响应体等信息，发送给网络进程，等网络进程接收后开始解析响应头内容 <ol><li><strong>重定向</strong>，状态码是301或302，从响应头获取Location字段发起新的请求</li><li><strong>响应数据类型处理</strong>，根据Content-Type确定服务器返回响应体是什么类型，浏览器根据类型确定是HTML页面还是需要下载</li></ol></li></ul></li><li><p><strong>准备渲染进程</strong></p><ul><li>浏览器会为每个页面分配一个渲染进程，如果从A页面打开B页面且同一站点则复用A页面的进程</li><li>此时还不能进入文档解析状态，此时文档数据还在网络进程</li></ul></li><li><p><strong>提交文档</strong></p><ul><li>就是网络进程将收到的HTML数据提交给渲染进程。</li><li>浏览器收到网络进程的响应头之后，向渲染进程发起提交文档的消息</li><li>渲染进程收到后会和网络进程建立数据传输。文档传输完，渲染进程返回确认提交的消息给浏览器进程</li><li>浏览器进程收到确认提交后，更新浏览器状态，包括安全状态、地址栏的URL、前进后退的历史状态，最后更新Web页面</li></ul></li><li><p><strong>渲染阶段</strong></p><ul><li>文档被提交后，渲染进程开始页面解析和子资源加载</li><li>页面生成完成后，渲染进程会发送一个消息给浏览器进程，浏览器进程会停止标签页的加载动画</li></ul></li></ol>',5),a=[s];function n(_,p,c,d,u,g){return o(),i("div",null,a)}const h=l(e,[["render",n]]);export{f as __pageData,h as default};
